const numbers = [1, 2, 3, 4];
numbers.forEach(num => console.log(num));
// Executes a function once for each array element.

const nums = [1, 2, 3];
const squares = nums.map(n => n * n);
console.log(squares); // [1, 4, 9]
// Creates a new array by applying a function to each element.

const ages = [12, 18, 25, 30];
const adults = ages.filter(age => age >= 18);
console.log(adults); // [18, 25, 30]
// Returns a new array with elements that pass the condition.

const nums = [1, 2, 3, 4];
const sum = nums.reduce((acc, curr) => acc + curr, 0);
console.log(sum); // 10
// Reduces the array to a single value by accumulating results.

const name = 'John';
const greeting = `Hello, ${name}!`;
console.log(greeting); // Hello, John!
// Template literals allow embedding expressions inside strings.

const colors = ['red', 'green', 'blue'];
const [first, second] = colors;
console.log(first, second); // red green
// Destructuring extracts array elements into variables.

const person = {name: 'Alice', age: 30};
const {name, age} = person;
console.log(name, age); // Alice 30
// Allows extracting properties from objects into variables.

const numbers = [1, 2, 3, 4, 5];
const doubledEven = numbers
  .filter(n => n % 2 === 0)
  .map(n => n * 2);
console.log(doubledEven); // [4, 8]
// You can chain methods to process data in multiple steps.
